"""Step 7d (after 13). Section 3.5, "How Much Do Policy Shocks Explain?", and its appendix (Part 2A of explore_decomp/INTEGRATION_PLAN.md; FS-A76 D6-D9):
fig_decomp_hd.pdf (historical contributions of policy-direction shocks, 1974-2026, model from 1973, with the measured-surprise line; four panels), tab_decomp_shares.tex (24-month variance
shares, models from 1996 and from 1973), tab_decomp_full.tex and tab_decomp_diag.tex (appendix), report/numbers_decomp.tex (macros bl:dc:*); asserts the claims made in the text.
   python3 07d_report_decomp.py"""
import os
import numpy as np, pandas as pd
import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt
from lib.paths import RESULTS, REPORT, OUT

ML = [r"% generated by baseline/07d_report_decomp.py: do not edit"]; BAD = []
def mac(k, v): ML.append(r"\expandafter\gdef\csname bl:dc:" + k + r"\endcsname{" + str(v) + "}")
def chk(name, ok):
    if not ok: BAD.append(name)
def pct(x): return f"{100 * x:.1f}"
def num(x): s = f"{abs(x):.2f}"; return ("$-$" if x < 0 and s != "0.00" else "") + s

S = pd.read_csv(RESULTS / "decomp_shares.csv"); S["fci"] = S.fci.astype(str); B = pd.read_csv(RESULTS / "decomp_bands.csv"); B["fci"] = B.fci.astype(str)
O = pd.read_csv(RESULTS / "decomp_overlap.csv"); O["fci"] = O.fci.astype(str); DG = pd.read_csv(RESULTS / "decomp_diagnostics.csv"); DG["fci"] = DG.fci.astype(str); SIM = pd.read_csv(RESULTS / "decomp_sim.csv")
def share(fci, model, h, era, src, var, mode="infer"):
    g = S[(S["mode"] == mode) & (S.fci == fci) & (S.model == model) & (S.h == h) & (S.era == era) & (S.source == src)]; return float(g[var].iloc[0])
def band(fci, model, h, era, src, var, mode="infer"):
    g = B[(B["mode"] == mode) & (B.fci == fci) & (B.model == model) & (B.h == h) & (B.era == era) & (B.source == src) & (B["var"] == var)]
    return (float(g.p5.iloc[0]), float(g.p95.iloc[0])) if len(g) else (np.nan, np.nan)

# ---------------------------------------------------------------- macros: shares (percent), bands, splice, diagnostics, simulation
ROWS = [("meas", "1996-2026", "measured", "Measured window surprises, 1996--2026"), ("pd90", "1990-2026", "daily_all", "Policy-direction shocks, 1990--2026"),
        ("other90", "1990-2026", "daily_other", r"\quad of which on days without an announcement"), ("pd74", "1974-1989", "spliced", "Policy-direction shocks, 1974--1989")]
for fci, fk in (("rstar", "yes"), ("0", "no")):
    for model in (1996, 1973):
        for h in (12, 24, 36):
            for key, era, src, _ in ROWS:
                for v in ("u", "pi", "pol") + (("idx",) if fci == "rstar" else ()):
                    k = f"{fk}:{model}:{key}:{v}:{h}"; x = share(fci, model, h, era, src, v); lo, hi = band(fci, model, h, era, src, v)
                    mac(k, pct(x)); mac(k + ":lo", pct(lo) if np.isfinite(lo) else "--"); mac(k + ":hi", pct(hi) if np.isfinite(hi) else "--")
                    for alt in ("absorb", "infer_unscaled"):
                        g = S[(S["mode"] == alt) & (S.fci == fci) & (S.model == model) & (S.h == h) & (S.era == era) & (S.source == src)]
                        if len(g): mac(f"{k}:{alt}", pct(float(g[v].iloc[0])))
for fci, fk in (("rstar", "yes"), ("0", "no")):
    r = O[O.fci == fci].iloc[0]; mac(f"{fk}:splice:corr", f"{r['corr']:.2f}"); mac(f"{fk}:splice:scale", f"{r.scale:.2f}")
for _, r in DG.iterrows():
    k = f"diag:{r.step}:{'no' if r.fci == '0' else 'yes'}:{str(r.start)[:4]}"
    mac(k + ":r2", f"{100 * r.r2_z_u:.1f}"); mac(k + ":corr", f"{r.corr_e_z:.2f}"); mac(k + ":plead", f"{r.p_leads:.2f}"); mac(k + ":varratio", f"{r.var_ratio:.0f}")
for c in ("r2_z_u", "corr_e_z", "var_ratio"): mac(f"sim:{c}:med", f"{(100 if c == 'r2_z_u' else 1) * SIM[c].median():.{1 if c != 'var_ratio' else 0}f}")
mac("sim:n", len(SIM))
D = pd.read_csv(OUT / "decomp" / "daily_shocks_rstar_rstar_infer.csv", parse_dates=["date"]); ann = D[D.ann == 1]
mac("ann:corr", f"{np.corrcoef(ann.s, ann.ns)[0, 1]:.2f}")

# ---------------------------------------------------------------- history (model from 1973, infer)
HD = {m: pd.read_csv(RESULTS / f"decomp_hd_rstar_rstar_model{m}_infer.csv") for m in (1973, 1996)}
def avg(model, var, a, b, col="spliced"):
    g = HD[model][HD[model]["var"] == var].set_index("month")[col]; g.index = pd.PeriodIndex(g.index, freq="M"); return float(g.loc[a:b].mean())
EPIS = [("e7980", "1979-01", "1980-12"), ("e8284", "1982-01", "1984-12"), ("e0103", "2001-01", "2003-12"), ("e2021", "2020-04", "2021-12"), ("e2224", "2022-06", "2024-06")]
for key, a, b in EPIS:
    for v in ("u", "pi", "pol", "idx"): mac(f"hist:{key}:{v}", num(avg(1973, v, a, b)))
mac("hist:pi2122", num(avg(1973, "pi", "2021-01", "2022-12")))

# ---------------------------------------------------------------- Table: 24-month variance shares (main text)
def cellp(fci, model, h, era, src, v, bands=True):
    x = share(fci, model, h, era, src, v); lo, hi = band(fci, model, h, era, src, v)
    return pct(x), (f"[{pct(lo)}, {pct(hi)}]" if bands and np.isfinite(lo) else "")
body = []
for key, era, src, lab in ROWS:
    cs = [cellp("rstar", m, 24, era, src, v) for m in (1996, 1973) for v in ("u", "pi")]
    body += [f"{lab} & " + " & ".join(c[0] for c in cs) + r"\\", " & " + " & ".join(rf"{{\scriptsize {c[1]}}}" for c in cs) + r"\\"]
(REPORT / "tab_decomp_shares.tex").write_text("\n".join([r"\begin{table}[tp]\centering\small", r"\caption{How Much Policy Shocks Explain: Variance Shares at 24 Months}\label{tab:decompshares}",
    r"\begin{tabular}{lcccc}\toprule & \multicolumn{2}{c}{Model from 1996} & \multicolumn{2}{c}{Model from 1973}\\ \cmidrule(lr){2-3}\cmidrule(lr){4-5} Shocks & Unemployment gap & Core inflation & Unemployment gap & Core inflation\\ \midrule",
    *body, r"\bottomrule\end{tabular}",
    r"\begin{flushleft}\footnotesize\textit{Notes:} Percent of the 24-month forecast-error variance (monthly VAR in monthly averages from 1973, 12 lags) accounted for by the contributions of the shocks of the last 24 months, propagated through the $r^*$-gap model with the FCI (12 lags, March--December 2020 dropped) with monthly equations from 1996 or from 1973; shares over the stated period, March--December 2020 excluded. Measured window surprises: the 252 announcements. Policy-direction shocks: the daily movement of the two-year yield and the FCI in the direction of the window response, recovered from the daily block on every day from 1990; before 1990 from the monthly VAR, scaled to the daily shocks' size. Brackets: 90\% bootstrap bands of Note B's responses.\end{flushleft}", r"\end{table}"]) + "\n")

# ---------------------------------------------------------------- appendix: full shares, robustness, diagnostics
SRCF = [("1974-1989", "spliced", "1974--1989, policy-direction (monthly, scaled)"), ("1990-2026", "daily_all", "1990--2026, policy-direction (daily)"), ("1990-2026", "daily_other", r"\quad days without an announcement"),
        ("1990-2026", "daily_ann", r"\quad announcement days"), ("1990-2026", "measured", r"\quad measured surprises"), ("1996-2026", "daily_all", "1996--2026, policy-direction (daily)"), ("1996-2026", "measured", r"\quad measured surprises")]
lines = []
for fci, ft in (("rstar", "Yield and FCI"), ("0", "Yield alone")):
    for model in (1996, 1973):
        lines.append(rf"\addlinespace\multicolumn{{6}}{{l}}{{\textit{{{ft}, model from {model}}}}}\\")
        for era, src, lab in SRCF:
            vals = []
            for v in ("u", "pi", "pol", "idx"):
                if v == "idx" and fci == "0": vals.append("--"); continue
                x = share(fci, model, 24, era, src, v); lo, hi = band(fci, model, 24, era, src, v); vals.append(pct(x) + (rf" {{\scriptsize [{pct(lo)}, {pct(hi)}]}}" if np.isfinite(lo) else ""))
            rob = []
            for alt in ("absorb", "infer_unscaled"):
                g = S[(S["mode"] == alt) & (S.fci == fci) & (S.model == model) & (S.h == 24) & (S.era == era) & (S.source == src)]
                rob.append(f"{pct(float(g['u'].iloc[0]))}/{pct(float(g['pi'].iloc[0]))}" if len(g) else "--")
            lines.append(f"{lab} & " + " & ".join(vals) + " & " + " & ".join(rob) + r"\\")
(REPORT / "tab_decomp_full.tex").write_text("\n".join([r"\begin{table}[tp]\centering\scriptsize\setlength{\tabcolsep}{2pt}", r"\caption{Variance Shares at 24 Months: All Sources and Robustness}\label{tab:decompfull}",
    r"\resizebox{\textwidth}{!}{\begin{tabular}{lcccccc}\toprule Shocks & Unemployment gap & Core inflation & Two-year yield & FCI & 2020 absorbed (u/$\pi$) & Unscaled before 1990 (u/$\pi$)\\ \midrule", *lines, r"\bottomrule\end{tabular}}",
    r"\begin{flushleft}\footnotesize\textit{Notes:} Percent of the 24-month forecast-error variance; see Table~\ref{tab:decompshares}. 2020 absorbed: the month dummies absorb March--December 2020 (the recovered shocks of those days set to zero). Unscaled: monthly-recovered shocks before 1990 not scaled to the daily shocks' size. Brackets: 90\% bootstrap bands.\end{flushleft}", r"\end{table}"]) + "\n")
dl = []
for _, r in DG.sort_values(["start", "step", "fci"]).iterrows():
    dl.append(f"{ {'nom': 'Nominal', 'real': 'Real', 'rstar': '$r^*$-gap'}[r.step]} & {'with FCI' if r.fci != '0' else 'yield alone'} & {str(r.start)[:4]} & {100 * r.r2_z_u:.1f} & {100 * r.r2_z_u_leads:.1f} & {r.p_leads:.2f} & {r.corr_e_z:.2f} & {r.var_ratio:.0f}" + r"\\")
q = SIM.quantile([0.05, 0.5, 0.95])
dl.append(r"\addlinespace" + rf"Simulation, model as truth (median [5th, 95th]) & & & {100 * q.r2_z_u[0.5]:.1f} [{100 * q.r2_z_u[0.05]:.1f}, {100 * q.r2_z_u[0.95]:.1f}] & & & {q.corr_e_z[0.5]:.2f} [{q.corr_e_z[0.05]:.2f}, {q.corr_e_z[0.95]:.2f}] & {q.var_ratio[0.5]:.0f}" + r"\\")
(REPORT / "tab_decomp_diag.tex").write_text("\n".join([r"\begin{table}[tp]\centering\scriptsize", r"\caption{Can a Monthly VAR Recover the Window Surprise?}\label{tab:decompdiag}",
    r"\begin{tabular}{lllrrrrr}\toprule Yield & FCI & Start & $R^2$, innovations (\%) & $R^2$, with 6 leads (\%) & $p$, leads & Correlation & Variance ratio\\ \midrule", *dl, r"\bottomrule\end{tabular}",
    r"\begin{flushleft}\footnotesize\textit{Notes:} Monthly VAR in monthly averages (12 lags, March--December 2020 dropped). $R^2$: the month's sum of the measured surprises regressed on the month's VAR innovations (and on six months of later innovations); $p$: Wald test that the leads add nothing. Correlation: between the shock recovered from the innovations in the window direction and the measured surprise. Variance ratio: the recovered shock's variance under invertibility over the measured surprise's (1996--2026). Simulation: 200 samples generated by the $r^*$-gap model with the FCI, in which the policy shock is the window surprise by construction.\end{flushleft}", r"\end{table}"]) + "\n")

# ---------------------------------------------------------------- figure: historical contributions (model from 1973)
BLUE, ORANGE, INK, GREY = "#2a78d6", "#eb6834", "#0b0b0b", "#6b6a66"
plt.rcParams.update({"font.size": 8, "axes.edgecolor": GREY, "axes.labelcolor": INK, "text.color": INK, "xtick.color": INK, "ytick.color": INK,
                     "axes.spines.top": False, "axes.spines.right": False, "axes.grid": True, "grid.color": "#e6e5e1", "grid.linewidth": 0.6, "axes.axisbelow": True})
ma12 = lambda x: pd.Series(x).rolling(12).mean().values
names = [("u", "Unemployment gap (pp)"), ("pi", "Core PCE inflation, 12-month average (pp)"), ("pol", "Two-year yield, $r^*$-gap (pp)"), ("idx", "FCI, $r^*$-gap (pp)")]
fig, ax = plt.subplots(2, 2, figsize=(7.2, 5.0), sharex=True); ax = ax.ravel(); hd = HD[1973]
zb = np.load(OUT / "decomp" / "bands_hd_rstar_rstar_model1973_infer.npz", allow_pickle=True)["hd"].astype(float)
for k, (v, lab) in enumerate(names):
    a = ax[k]; g = hd[hd["var"] == v]; t = pd.PeriodIndex(g.month, freq="M").to_timestamp(); f = ma12 if v == "pi" else np.asarray
    z = zb[:, :, k]; z = np.array([ma12(r) for r in z]) if v == "pi" else z
    a.fill_between(t, np.nanpercentile(z, 5, axis=0), np.nanpercentile(z, 95, axis=0), color=BLUE, alpha=0.15, lw=0)
    h1 = a.plot(t, f(g.spliced.values), color=BLUE, lw=1.4)[0]; h2 = a.plot(t, f(g.measured.values), color=ORANGE, lw=1.1)[0]
    a.axhline(0, color=GREY, lw=0.7); a.set_title(lab, loc="left", fontsize=8.5)
fig.legend([h1, h2], ["Policy-direction shocks (90% band)", "Measured window surprises"], loc="lower center", ncol=2, frameon=False, fontsize=7.5)
fig.tight_layout(rect=[0, 0.05, 1, 1]); fig.savefig(REPORT / "fig_decomp_hd.pdf"); plt.close(fig)

# ---------------------------------------------------------------- claims made in Section 3.5 and the appendix
for m in (1996, 1973):
    chk(f"model {m}: measured surprises explain under 2 percent of the 24-month variance of unemployment and core inflation", all(share("rstar", m, 24, "1996-2026", "measured", v) < 0.02 for v in ("u", "pi")))
    chk(f"model {m}: policy-direction shocks 1990-2026 explain more than measured surprises (u, pi) and their 90% band excludes zero", all(share("rstar", m, 24, "1990-2026", "daily_all", v) > share("rstar", m, 24, "1996-2026", "measured", v) and band("rstar", m, 24, "1990-2026", "daily_all", v)[0] > 0 for v in ("u", "pi")))
    chk(f"model {m}: almost all of the policy-direction share comes from days without an announcement", all(share("rstar", m, 24, "1990-2026", "daily_ann", v) < 0.2 * share("rstar", m, 24, "1990-2026", "daily_all", v) for v in ("u", "pi")))
    chk(f"model {m}: policy-direction shocks account for most (over 50 percent) of the 2-year yield's 24-month variance (1990-2026)", share("rstar", m, 24, "1990-2026", "daily_all", "pol") > 0.5)
chk("splice: daily- and monthly-recovered shocks correlate above 0.4 over the overlap (with the FCI)", O[O.fci == "rstar"]["corr"].iloc[0] > 0.4)
chk("announcement days: the daily-recovered shock correlates above 0.5 with the measured surprise", np.corrcoef(ann.s, ann.ns)[0, 1] > 0.5)
chk("monthly VAR: the surprise's R-squared on the month's innovations below 5 percent in every case", (DG.r2_z_u < 0.05).all())
chk("simulation with the model as truth: median R-squared below 5 percent (the failure is a property of the model, not the data)", SIM.r2_z_u.median() < 0.05)
sg = lambda key, v: avg(1973, v, *next((a, b) for k_, a, b in EPIS if k_ == key))
chk("history (model from 1973): policy-direction shocks eased in 1979-80, 2001-03 and 2020-21 and tightened in 1982-84 and 2022-24 (contributions to the two-year yield)", sg("e7980", "pol") < 0 and sg("e0103", "pol") < 0 and sg("e2021", "pol") < 0 and sg("e8284", "pol") > 0 and sg("e2224", "pol") > 0)
chk("history: the 1979-80 and 2020-21 easings raised core inflation and lowered unemployment; the 1982-84 tightening did the reverse", sg("e7980", "pi") > 0 > sg("e7980", "u") and sg("e2021", "pi") > 0 > sg("e2021", "u") and sg("e8284", "pi") < 0 < sg("e8284", "u"))
chk("history: policy-direction shocks added about 1 percentage point or more to core inflation over 2021-22", avg(1973, "pi", "2021-01", "2022-12") > 0.8)
chk("abstract: policy-direction shocks account for about a tenth (6 to 14 percent) of the 24-month variance of core inflation, both models and both periods", all(0.06 < share("rstar", m, 24, era, src, "pi") < 0.14 for m in (1996, 1973) for era, src in (("1990-2026", "daily_all"), ("1974-1989", "spliced"))))
if os.environ.get("CLAIMS_REPORT"): print("FAILED CLAIMS:\n  " + "\n  ".join(BAD))
else: assert not BAD, "claims in Section 3.5 no longer hold: " + "; ".join(BAD)
(REPORT / "numbers_decomp.tex").write_text("\n".join(ML) + "\n")
from lib import latex_style as LST
LST.restyle_dir(REPORT)
print("decomposition exhibits written to", REPORT)
